// Standalone scenario prototype. Never reads or writes production progress keys.
const asset = '../../../apps/web/public/images/mio/';
const key = 'physicslab-prototype-motion-v1';
const defaults = {version:1, lastScreen:'walk', started:false, step:0, walkAnswer:'', slow:5, stop:false, observed:false, answer:'', checked:false, attempts:0, explanation:'', note:''};
let state = {...defaults}, storageBlocked = false;
const storageError = document.querySelector('#storage-error');
try {
  const raw = localStorage.getItem(key);
  if (raw) {
    const saved = JSON.parse(raw);
    if (saved.version !== 1 || Object.keys(defaults).some(k => typeof saved[k] !== typeof defaults[k])) throw new Error('Unsupported draft');
    state = saved;
    state.step = Math.max(0, Math.min(2, Math.round(state.step)));
    state.slow = Math.max(1, Math.min(9, Math.round(state.slow)));
  }
} catch { storageBlocked = true; showStorageError(); }
function showStorageError() { storageError.hidden=false; storageError.textContent='Черновик прототипа недоступен. Существующие данные не изменены. Скопируй свой текст перед закрытием.'; }
function save(patch={}) { Object.assign(state,patch); if(storageBlocked) return false; try { localStorage.setItem(key,JSON.stringify(state)); return true; } catch { showStorageError(); return false; } }
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button = (text,target,secondary=false) => `<a class="${secondary?'quiet':'button'}" href="#${target}">${text}<span aria-hidden="true">→</span></a>`;
const pageNames = {walk:'Путь и перемещение',bridge:'Два смысла средней скорости',speed:'Опыт со средней скоростью',challenge:'Самостоятельная задача',summary:'Итог поездки'};
const scene = (name,alt,quote) => `<figure class="scene"><img src="${asset}textbook-${name}-v1.png" alt="${alt}"><figcaption><strong>Мио</strong>${quote}</figcaption></figure>`;
const explanation = `<details class="support"><summary>Разобраться в объяснении</summary><h3>Путь и перемещение</h3><p>Путь — вся длина маршрута. Перемещение — вектор от начальной точки к конечной. У него есть направление и модуль. После возвращения в начало перемещение равно нулю, но путь уже пройден.</p><h3>Две средние скорости</h3><p>Средняя путевая скорость = весь путь / всё время. Средняя скорость перемещения = перемещение / всё время. Для замкнутой прогулки вторая равна нулю.</p><p>На каждом участке с постоянной скоростью путь равен скорости, умноженной на время. Для всей поездки сначала складываем пути, затем делим на полное время, включая остановки внутри выбранного промежутка.</p><p>Полусумма двух скоростей подходит при равных временах. При разных временах она не является общим правилом.</p></details>`;
function lessonTop(label) {return `<div class="lesson-top"><a class="back" href="#learn">← Выбрать тему</a><small>${label}</small></div>`;}
function home() {
  const last = pageNames[state.lastScreen] ? state.lastScreen : 'walk';
  return `<section class="home-intro"><div><p class="eyebrow">Физика, в которой можно разобраться</p><h1>Посмотри, что меняется.</h1><p class="lead">Опыты, понятные объяснения и задачи по школьной физике. Начни с вопроса, который тебя зацепил.</p></div><img class="home-art" src="${asset}mio-thinking-v1.png" alt="Мио с блокнотом"></section>
  ${state.started?`<aside class="resume" aria-label="Продолжить свою работу"><div><p class="eyebrow">С прошлого раза</p><h2>${pageNames[last]}</h2><small>${last==='speed'?`Ты выбрал ${state.slow} с медленного движения${state.stop?' и остановку':''}.`:'Можно вернуться к сохранённым ответам и наблюдению.'}</small></div>${button('Продолжить',last)}</aside>`:''}
  <section class="entry"><div><p class="eyebrow">Начать с небольшого исследования</p><h2>Вернулась в начало. А путь куда делся?</h2><p class="muted">Мио забыла блокнот. Одна прогулка поможет различить путь, перемещение и два смысла средней скорости.</p><p class="route-line">Путь и перемещение → Средняя скорость</p><div class="actions">${button('Посмотреть прогулку','walk')}<a class="link" href="#learn">Выбрать конкретную тему</a></div></div><div class="entry-links"><a href="#speed"><div><strong>Не сходится средняя скорость?</strong><small>Измени время и проверь способ расчёта</small></div><span>→</span></a><a href="#challenge"><div><strong>Хочу сразу решить задачу</strong><small>Другая поездка, твой расчёт</small></div><span>→</span></a><a href="http://127.0.0.1:3000/practice/exam-demo"><div><strong>Подготовка к ЦТ/ЦЭ</strong><small>Отдельная диагностика по доступным темам</small></div><span>↗</span></a></div></section>`;
}
function learn() { return `<div class="topics"><p class="eyebrow">Учиться</p><h1>С каким вопросом ты пришёл?</h1><p class="lead">Можно пройти темы по порядку или начать с нужного места.</p><a class="topic-row" href="#walk"><div><h2>Путь и перемещение</h2><p>Как можно пройти 40 метров и вернуться в начало?</p></div><span>→</span></a><a class="topic-row" href="#bridge"><div><h2>Два смысла средней скорости</h2><p>Какую величину мы делим на время?</p></div><span>→</span></a><a class="topic-row" href="#speed"><div><h2>Средняя скорость на участках</h2><p>Почему две скорости нельзя всегда усреднять?</p></div><span>→</span></a>${explanation}<details><summary>Что пригодится перед началом</summary><p>Метры и секунды, сложение и деление. Скорость 2 м/с означает: за каждую секунду равномерного движения проходит 2 м. За 5 с — 10 м.</p><p>Стрелка от начала к концу показывает перемещение. Если вводим ось, знак её проекции зависит от выбранного положительного направления. В прогулке все положения рассматриваем относительно здания.</p></details></div>`; }
function walk() {const back=state.step===2; return `${lessonTop('Путь и перемещение · относительно здания')}<header class="lesson-title"><p class="eyebrow">Одна прогулка — два вопроса</p><h1>Вернулась. Но ведь ходила?</h1><p class="lead">Мио дошла до скамейки и вернулась за блокнотом. От двери до скамейки 20 метров.</p></header><div class="workspace">${scene('path','Мио берёт забытый блокнот у двери','«Начало и конец совпали. Но шагомер насчитал сорок метров».')}<section class="work"><h2>Выбери момент прогулки</h2><div class="segmented" aria-label="Момент прогулки">${['У двери','У скамейки','Вернулась'].map((v,i)=>`<button data-step="${i}" aria-pressed="${state.step===i}">${v}</button>`).join('')}</div><svg class="physical-route" viewBox="0 0 400 88" role="img" aria-label="${state.step===0?'Движение ещё не началось':back?'20 метров туда и 20 обратно':'20 метров от двери к скамейке'}"><text x="0" y="15">Дверь</text><text x="400" y="15" text-anchor="end">Скамейка</text>${state.step>0?'<path d="M5 36 H390 l-8 -5 m8 5 l-8 5"/><text x="195" y="30" text-anchor="middle">20 м туда</text>':''}${back?'<path d="M390 67 H5 l8 -5 m-8 5 l8 5"/><text x="195" y="61" text-anchor="middle">20 м обратно</text>':''}</svg><div class="readings"><div><span>Пройденный путь</span><strong class="accent">${state.step*20} <em>м</em></strong></div><div><span>Модуль перемещения</span><strong>${state.step===1?20:0} <em>м</em></strong></div></div><p>${back?'Путь учитывает оба участка. Перемещение соединяет начало и конец — здесь это одна точка.':state.step===1?'На этом прямом участке путь и модуль перемещения равны.':'Пока не началось движение, обе величины равны нулю.'}</p>${back?`<fieldset class="question"><legend>Перемещение равно нулю. Что из этого следует?</legend>${['Мио всё время стояла','Мио оказалась там, откуда вышла'].map((v,i)=>`<label class="option"><input type="radio" name="walk-answer" value="${i}" ${state.walkAnswer===String(i)?'checked':''}>${v}</label>`).join('')}</fieldset><p class="feedback" role="status">${state.walkAnswer==='0'?'Вспомни два пройденных участка. Нулевое перемещение описывает итоговое положение, а не отсутствие движения.':state.walkAnswer==='1'?'Да. По начальному и конечному положению нельзя узнать весь маршрут.':''}</p><div class="handoff"><h2>А если засечь время?</h2><p class="muted">Путь есть, перемещение нулевое. Какая тогда средняя скорость?</p><div class="actions">${button('Добавить время к прогулке','bridge')}</div></div>`:''}</section></div>${explanation}`; }
function bridge() {return `${lessonTop('От маршрута — к скорости')}<header class="lesson-title"><p class="eyebrow">Тот же маршрут. Новый вопрос.</p><h1>Средняя скорость может быть нулевой?</h1><p class="lead">Вся прогулка туда и обратно заняла 20 секунд. Сравним два разных описания.</p></header><div class="bridge-scene">${scene('path','Мио вернулась к двери за блокнотом','«Путь никуда не делся. Значит, сначала уточним, какую скорость считаем».')}<section class="work"><div class="readings"><div><span>Весь путь / всё время</span><strong class="accent">2 <em>м/с</em></strong><small>40 м / 20 с</small></div><div><span>Перемещение / всё время</span><strong>0 <em>м/с</em></strong><small>Перемещение равно нулю</small></div></div><h2>Оба результата верны.</h2><p>Первый — средняя путевая скорость. Второй — средняя скорость перемещения. Они отвечают на разные вопросы.</p><div class="handoff"><h2>А если ехать то медленно, то быстро?</h2><p class="muted">Дальше будем считать среднюю путевую скорость. Двух скоростей хватит для ответа — или важно ещё время?</p><div class="actions">${button('Проверить на двух участках','speed')}</div></div></section></div>${explanation}`;}
function speed() { const t=state.slow,fast=10-t,d=2*t+8*fast,total=10+(state.stop?10:0),avg=d/total; return `${lessonTop('Средняя путевая скорость')}<header class="lesson-title"><p class="eyebrow">Проверь догадку Мио</p><h1>Две скорости. Один ответ?</h1><p class="lead">Велосипедист едет по прямой: сначала 2 м/с, затем 8 м/с. На каждом участке скорость постоянна.</p></header><div class="workspace">${scene('average','Мио у велосипеда сверяет время на секундомере',state.observed&&t!==5?'«Скорости те же, а ответ другой. Значит, время нельзя выбросить из расчёта».':'«Может, просто (2 + 8) / 2 = 5 м/с? Проверим».')}<section class="work"><h2>Меняй время, оставь скорости</h2><div class="experiment-controls"><label for="slow">Медленный участок: <strong id="slow-label">${t} с</strong></label><input id="slow" type="range" min="1" max="9" value="${t}"><p class="muted">Быстрый участок: <strong id="fast-label">${fast} с</strong>. Всего в движении 10 с.</p><div class="preset"><button data-time="5" aria-pressed="${t===5}">Поровну</button><button data-time="8" aria-pressed="${t===8}">Дольше медленно</button></div><label class="stop"><input id="stop" type="checkbox" ${state.stop?'checked':''}>Включить ещё 10 с остановки в поездку</label></div><div class="actions"><button id="observe" class="button">Сравнить путь и время</button></div>${state.observed?`<div aria-live="polite"><table class="evidence"><caption class="hint-label">Условия выбранной поездки</caption><thead><tr><th>Участок</th><th>Время</th><th>Путь</th></tr></thead><tbody><tr><td>2 м/с</td><td>${t} с</td><td>${2*t} м</td></tr><tr><td>8 м/с</td><td>${fast} с</td><td>${8*fast} м</td></tr>${state.stop?'<tr><td>Остановка</td><td>10 с</td><td>0 м</td></tr>':''}</tbody><tfoot><tr><td>Вся поездка</td><td>${total} с</td><td>${d} м</td></tr></tfoot></table><div class="readings"><div><span>Средняя путевая скорость</span><strong class="accent">${avg.toLocaleString('ru-RU')} <em>м/с</em></strong><small>${d} м / ${total} с</small></div><div><span>Догадка Мио</span><strong>${avg!==5?'<s>5</s>':'5'} <em>м/с</em></strong><small>${avg===5?'Совпало. Измени время.':'В этих условиях не сработала.'}</small></div></div><p>${state.stop?'Остановка не добавляет пути, но входит в полное время этой поездки.':t===5?'Равные времена — случай, когда полусумма подходит. Проверь неравные времена.':'Мы поменяли время участков. Общий путь изменился, хотя две скорости остались прежними.'}</p></div><div class="actions">${button('Решить другую поездку','challenge')}<a class="link" href="#bridge">Вернуться к смыслу скорости</a></div>`:''}</section></div>${explanation}`; }
function challenge() {const correct=Number(state.answer.trim().replace(',','.'))===4 && state.answer.trim()!=='';return `${lessonTop('Самостоятельная задача · без подсказки Мио')}<section class="challenge"><p class="eyebrow">Другая поездка</p><h1>Теперь проверь свой способ.</h1><p class="condition">Робот двигался 6 секунд со скоростью 3 м/с, затем 3 секунды со скоростью 6 м/с. Остановок не было.</p><form id="answer-form"><label for="answer">Средняя путевая скорость за всю поездку</label><div class="answer-row"><input id="answer" type="text" inputmode="decimal" autocomplete="off" maxlength="40" value="${esc(state.answer)}"><span>м/с</span></div><button class="button" type="submit">Проверить</button></form>${state.checked?`<p class="feedback" role="status">${correct?`${state.attempts>1?'Теперь получилось.':'Верно.'} Робот прошёл 18 + 18 = 36 м за 9 с. Средняя путевая скорость — 4 м/с.`:'Найди путь каждого участка. Две скорости дают 4,5 м/с при усреднении, но робот ехал с ними разное время.'}</p>`:''}${state.checked&&correct?`<div class="actions">${button('Вернуться к результату исследования','summary')}</div>`:''}<details><summary>Нужна опора для расчёта</summary><p>За первые 6 секунд путь равен 3 · 6. За следующие 3 секунды — 6 · 3. Что нужно сделать с этими путями и временами?</p><a class="link" href="#speed">Проверить способ в опыте →</a></details></section>`;}
function summary() {return `${lessonTop('Результат исследования')}<section class="challenge"><p class="eyebrow">Что осталось после поездки</p><h1>Удобный ответ нужно проверить.</h1><p class="lead">Для средней путевой скорости считаем весь путь и всё время. Полусумма двух скоростей работает при равных временах.</p><details open><summary>Объяснить на своём примере</summary><label for="explanation">Скорости остались прежними. Почему средняя изменилась, когда ты изменил время участков?</label><textarea id="explanation" maxlength="10000" placeholder="Можно опереться на путь каждого участка">${esc(state.explanation)}</textarea><p class="note-status" id="explanation-status">Необязательно. Твой текст сохраняется, но не оценивается автоматически.</p></details><details><summary>Добавить личную заметку</summary><label for="note">Что хочешь оставить для себя?</label><textarea id="note" maxlength="10000">${esc(state.note)}</textarea><p class="note-status" id="note-status">Заметка необязательна и не влияет на результат задачи.</p></details><div class="actions">${button('Моя работа','notebook')}<a class="link" href="http://127.0.0.1:3000/practice/family/average-speed-segments">Ещё задачи на сайте ↗</a></div><div class="handoff"><h2>Что средняя скорость ещё не рассказывает?</h2><p>Она описывает всю поездку одним числом. Как именно скорость менялась внутри поездки — другой вопрос, с которого начинается изучение ускорения.</p><a class="link" href="#home">Вернуться на главную →</a></div></section>`;}
function notebook() {return `<section class="challenge"><p class="eyebrow">Моя работа</p><h1>К чему можно вернуться</h1>${state.started?`<div class="resume"><div><h2>${pageNames[state.lastScreen]||pageNames.walk}</h2><p class="muted">Сохранённое место в исследовании</p></div>${button('Открыть',pageNames[state.lastScreen]?state.lastScreen:'walk')}</div>`:'<p class="lead">Здесь появится начатое исследование. Писать заметки для этого не нужно.</p>'}${state.explanation?`<div class="handoff"><h2>Моё объяснение</h2><p class="note-text">${esc(state.explanation)}</p><a class="link" href="#summary">Дополнить объяснение →</a></div>`:''}${state.note?`<div class="handoff"><h2>Личная заметка</h2><p class="note-text">${esc(state.note)}</p><a class="link" href="#summary">Открыть заметку →</a></div>`:''}<div class="actions">${button('Выбрать тему','learn',true)}</div><p class="hint-label">Это записи прототипа в этом браузере. Они не являются оценкой освоения темы.</p></section>`;}
const screens={home,learn,walk,bridge,speed,challenge,summary,notebook};
function render() {
  const focused=document.activeElement;
  const focusSelector=focused?.id?`#${CSS.escape(focused.id)}`:focused?.dataset.step!==undefined?`[data-step="${focused.dataset.step}"]`:focused?.dataset.time!==undefined?`[data-time="${focused.dataset.time}"]`:focused?.name==='walk-answer'?`[name="walk-answer"][value="${focused.value}"]`:null;
  const name=location.hash.slice(1)||'home',view=screens[name]?name:'home';
  if(pageNames[view]) save({started:true,lastScreen:view});
  document.querySelector('#app').innerHTML=screens[view]();
  document.querySelectorAll('header nav a').forEach(a=>{const active=(view==='home'&&a.hash==='#home')||(view==='notebook'&&a.hash==='#notebook')||(view!=='home'&&view!=='notebook'&&a.hash==='#learn');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{save({step:Number(b.dataset.step)});render();});
  document.querySelectorAll('[name=walk-answer]').forEach(b=>b.onchange=()=>{save({walkAnswer:b.value});render();});
  const slider=document.querySelector('#slow');
  if(slider){slider.oninput=()=>{document.querySelector('#slow-label').textContent=slider.value+' с';document.querySelector('#fast-label').textContent=(10-Number(slider.value))+' с';const result=document.querySelector('[aria-live="polite"]');if(result)result.hidden=true;save({slow:Number(slider.value),observed:false});};slider.onchange=()=>{render();};}
  document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{save({slow:Number(b.dataset.time),observed:false});render();});
  const stop=document.querySelector('#stop');if(stop)stop.onchange=()=>{save({stop:stop.checked,observed:false});render();};
  const observe=document.querySelector('#observe');if(observe)observe.onclick=()=>{save({observed:true});render();};
  const answer=document.querySelector('#answer');if(answer)answer.oninput=()=>{save({answer:answer.value,checked:false});const feedback=document.querySelector('.feedback');if(feedback)feedback.hidden=true;const next=document.querySelector('a[href="#summary"]');if(next)next.hidden=true;};
  const form=document.querySelector('#answer-form');if(form)form.onsubmit=e=>{e.preventDefault();save({checked:true,attempts:state.attempts+1});render();};
  for(const field of ['explanation','note']) {const input=document.getElementById(field);if(input)input.oninput=()=>{const ok=save({[field]:input.value});document.getElementById(field+'-status').textContent=ok?'Сохранено в этом браузере.':'Не удалось сохранить. Скопируй текст перед закрытием.';};}
  if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});
}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);const title=document.querySelector('h1');title.tabIndex=-1;title.focus({preventScroll:true});});
document.querySelector('#theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';};
render();
